input.command:
cat > "$TEMP/parse_ram.py" <<'PY'
import sys,re
lines=open(sys.argv[1]).read().splitlines()
i=0; blocks=[]
while i<len(lines):
    if lines[i].startswith('.ram_data'):
        hdr=lines[i]; data=[]; i+=1
        while i<len(lines) and not lines[i].startswith('.'):
            if lines[i].strip(): data.append(lines[i].strip())
            i+=1
        blocks.append((hdr,data))
    else: i+=1
print("total ram_data blocks:",len(blocks))
for hdr,data in blocks:
    joined=''.join(data)
    nz=joined.replace('0','')
    if nz:
        print("---",hdr,"nonzero len",len(nz))
        for row in data:
            if row.replace('0',''):
                print("  ",row)
PY
/c/Python314/python -I "$TEMP/parse_ram.py" "C:/Users/kenne/Documents/CSAW Final Challenge 2/work/re/crypto.asc" 2>&1 | head -60

