// ascon_engine.v - Ascon-AEAD128 (NIST SP 800-232) authenticated-encryption
// engine, one permutation round per clock. Reverse-engineered behavioral
// reconstruction of the crypto_eeprom_top accelerator datapath; verified bit-
// exact against the validated Python reference (work/sim/ascon_ref.py).
//
// Buffers (AD/MSG/OUT) are byte memories owned by the parent (crypto_top) and
// accessed here through simple read/write ports. Key/nonce/secret arrive as
// flat 128-bit inputs latched by the parent from the EEPROM image.
`default_nettype none

module ascon_engine #(
    parameter ABITS = 10            // byte-address width for buffers (512B)
)(
    input  wire        clk,
    input  wire        rst_n,
    input  wire        start,       // 1-cycle pulse
    input  wire [1:0]  op,          // 1=enc 2=dec 3=encrypt-secret
    input  wire [9:0]  ad_len,      // bytes
    input  wire [9:0]  msg_len,     // bytes
    input  wire [127:0] key,
    input  wire [127:0] nonce,      // effective nonce (parent applies cfg source)
    input  wire [127:0] secret,     // device secret (plaintext source for op=3)
    // AD buffer read
    output reg  [ABITS-1:0] ad_raddr,
    input  wire [7:0]  ad_rdata,
    // MSG buffer read (ciphertext for dec / plaintext for enc)
    output reg  [ABITS-1:0] msg_raddr,
    input  wire [7:0]  msg_rdata,
    // OUT buffer write
    output reg         out_we,
    output reg  [ABITS-1:0] out_waddr,
    output reg  [7:0]  out_wdata,
    // tag I/O
    input  wire [127:0] tag_in,     // expected tag for decrypt
    output reg  [127:0] tag_out,    // produced tag
    // control/status
    output reg         busy,
    output reg         done,
    output reg         auth_ok,
    output reg         auth_fail
);
    // ---- round constants ----
    function [7:0] rc(input [3:0] r);
        rc = 8'hf0 - {r,4'b0} + {4'b0,r}; // 0xf0 - r*0x10 + r (0xf0..0x4b)
    endfunction

    function [63:0] rotr(input [63:0] x, input integer n);
        rotr = (x >> n) | (x << (64-n));
    endfunction

    // one Ascon permutation round on {x0,x1,x2,x3,x4}
    task automatic perm_round(input [7:0] c);
        reg [63:0] x0,x1,x2,x3,x4,t0,t1,t2,t3,t4;
        begin
            x0=X0; x1=X1; x2=X2^{56'b0,c}; x3=X3; x4=X4;
            // S-box (bit-sliced)
            x0=x0^x4; x4=x4^x3; x2=x2^x1;
            t0=(~x0)&x1; t1=(~x1)&x2; t2=(~x2)&x3; t3=(~x3)&x4; t4=(~x4)&x0;
            x0=x0^t1; x1=x1^t2; x2=x2^t3; x3=x3^t4; x4=x4^t0;
            x1=x1^x0; x0=x0^x4; x3=x3^x2; x2=~x2;
            // linear diffusion
            X0 = x0 ^ rotr(x0,19) ^ rotr(x0,28);
            X1 = x1 ^ rotr(x1,61) ^ rotr(x1,39);
            X2 = x2 ^ rotr(x2, 1) ^ rotr(x2, 6);
            X3 = x3 ^ rotr(x3,10) ^ rotr(x3,17);
            X4 = x4 ^ rotr(x4, 7) ^ rotr(x4,41);
        end
    endtask

    localparam [63:0] IV = 64'h00001000808c0001;

    reg [63:0] X0,X1,X2,X3,X4;
    reg [63:0] k0,k1;

    // FSM
    localparam S_IDLE=0, S_INIT=1, S_INITK=2, S_ADBLK=3, S_ADP=4, S_DOM=5,
               S_MSGBLK=6, S_MSGP=7, S_FINK=8, S_FINP=9, S_FINK2=10, S_TAG=11, S_DONE=12;
