                inblk = padblk(ad_block, cur_adlen, blk);
                X0<=X0^inblk[127:64]; X1<=X1^inblk[63:0];
                rnd<=4; st<=S_ADP;
            end
            S_ADP: begin
                do_round(rnd);
                if (rnd==4'd11) begin
                    if (blk==nblk_ad-1) st<=S_DOM;
                    else begin blk<=blk+1; rd_blk<=blk+1; st<=S_AD; end
                end
                rnd<=rnd+1;
            end
            S_DOM: begin
                X4<=X4 ^ 64'h8000000000000000;
                blk<=0; rd_blk<=0; st<=S_MSG;
            end
