            S_FINK: begin X2<=X2^k0; X3<=X3^k1; rnd<=0; st<=S_FINP; end
            S_FINP: begin
                do_round(rnd);
                if (rnd==4'd11) st<=S_FINK2;
                rnd<=rnd+1;
            end
            S_FINK2: begin
                X3<=X3^k0; X4<=X4^k1; st<=S_TAG;
            end
            S_TAG: begin
                tag_out<={X3,X4};
                if (cur_op==2'd2) begin
                    if ({X3,X4}==tag_in) auth_ok<=1; else auth_fail<=1;
                end
