            X1 = x1 ^ rotr(x1,61) ^ rotr(x1,39);
            X2 = x2 ^ rotr(x2, 1) ^ rotr(x2, 6);
            X3 = x3 ^ rotr(x3,10) ^ rotr(x3,17);
            X4 = x4 ^ rotr(x4, 7) ^ rotr(x4,41);
        end
    endtask

