                case (cfg[3:2])
                    2'd0: eff_nonce <= r_nonce;
                    2'd1: eff_nonce <= host_nonce;
                    2'd2: eff_nonce <= r_nonce ^ host_nonce;
                    default: eff_nonce <= r_nonce;
                endcase
