            end
        end
    end

    // ---- combinational buffer read ----
    always @* begin
        if      (cmd_raddr < 16'h200) cmd_rdata = admem [cmd_raddr[8:0]];
        else if (cmd_raddr < 16'h400) cmd_rdata = msgmem[cmd_raddr[8:0]];
