// tb_crypto.v - functional self-test + golden-vector check + Trojan demos for
// the Ascon-AEAD128 accelerator. Mirrors tools/fpga_selftest.py exactly, and
// additionally verifies the DUT ciphertext/tag against the validated reference.
//
// Build clean:   iverilog -g2012 -s tb_crypto -o sim tb/tb_crypto.v rtl/*.v
// Build Trojan:  iverilog -g2012 -DTROJAN_A ... (A/B/C)
`timescale 1ns/1ps
`default_nettype none
module tb_crypto;
    `include "vectors.vh"

    reg clk=0, rst_n=0;
    always #5 clk=~clk;

    reg         prov_valid=0;
    reg [127:0] prov_key, prov_nonce, prov_secret;
    reg         cmd_we=0;
    reg [15:0]  cmd_waddr=0, cmd_raddr=0;
    reg [7:0]   cmd_wdata=0;
    wire [7:0]  cmd_rdata;
    reg         start=0;
    reg [7:0]   cfg=0;
    reg [9:0]   adlen=0, msglen=0;
    wire [7:0]  status;
    wire        ice_led;

    crypto_top dut(.clk(clk),.rst_n(rst_n),
        .prov_valid(prov_valid),.prov_key(prov_key),.prov_nonce(prov_nonce),.prov_secret(prov_secret),
        .cmd_we(cmd_we),.cmd_waddr(cmd_waddr),.cmd_wdata(cmd_wdata),
        .cmd_raddr(cmd_raddr),.cmd_rdata(cmd_rdata),
        .start(start),.cfg(cfg),.adlen(adlen),.msglen(msglen),
        .status(status),.ice_led(ice_led));

    localparam ST_BUSY=8'h01, ST_DONE=8'h02, ST_AUTH_OK=8'h04, ST_AUTH_FAIL=8'h08,
               ST_KEYS=8'h10, ST_ALIVE=8'h80;
    localparam OP_ENC=2'd1, OP_DEC=2'd2, OP_SEC=2'd3;

    integer npass=0, nfail=0;
    integer i;
    reg [511:0] rbuf;

    task chk(input [255:0] name, input ok);
        begin
            if (ok) begin npass=npass+1; $display("  PASS %0s", name); end
            else    begin nfail=nfail+1; $display("  FAIL %0s", name); end
        end
    endtask

    // write nbytes of a left-justified vector (byte0 = bits [511:504])
    task wr_vec(input [15:0] base, input [511:0] vec, input integer nbytes);
        begin
            for (i=0;i<nbytes;i=i+1) begin
                @(posedge clk); cmd_we<=1; cmd_waddr<=base+i[15:0];
                cmd_wdata<=vec[511-8*i -: 8];
            end
            @(posedge clk); cmd_we<=0;
        end
    endtask

    task rd_vec(input [15:0] base, input integer nbytes);
        begin
            rbuf = 512'b0;
            for (i=0;i<nbytes;i=i+1) begin
                cmd_raddr = base+i[15:0]; #1;
                rbuf[511-8*i -: 8] = cmd_rdata;
            end
        end
    endtask

    task run_op(input [7:0] c, input [9:0] al, input [9:0] ml);
        begin
            @(posedge clk); cfg<=c; adlen<=al; msglen<=ml; start<=1;
            @(posedge clk); start<=0;
            // wait done
            while (!(status & ST_DONE)) @(posedge clk);
        end
    endtask

    // --- scratch for checks ---
    reg [351:0] ct_g, msg_g; reg [127:0] tag_g;

    initial begin
        $dumpfile("tb/tb_crypto.vcd"); $dumpvars(0,tb_crypto);
        prov_key=V_KEY; prov_nonce=V_NONCE_EEPROM; prov_secret=V_SECRET;
        repeat(3) @(posedge clk); rst_n=1;
        repeat(2) @(posedge clk); prov_valid=1;  // EEPROM load
        @(posedge clk); prov_valid=0;
        repeat(2) @(posedge clk);

        $display("Link:");
        chk("accelerator responds", (status!=8'h00)&&(status!=8'hff)&&((status&ST_ALIVE)!=0));
        chk("key material loaded", (status & ST_KEYS)!=0);

        // ===== Encrypt / decrypt (host nonce) =====
        $display("Encrypt / decrypt:");
        wr_vec(16'h620, {V_HOST_NONCE,384'b0}, 16);
        wr_vec(16'h000, {V_AD,  {(512-136){1'b0}}}, V_AD_LEN);
        wr_vec(16'h200, {V_MSG, {(512-352){1'b0}}}, V_MSG_LEN);
        run_op({4'b0, 2'b01, OP_ENC}, V_AD_LEN[9:0], V_MSG_LEN[9:0]); // cfg=0x05 host+enc
        rd_vec(16'h400, V_MSG_LEN); ct_g = rbuf[511 -: 352];
        chk("ciphertext length matches plaintext", 1'b1);
        chk("ciphertext differs from plaintext", ct_g !== V_MSG);
        chk("ciphertext matches golden reference", ct_g === V_CT);
        rd_vec(16'h610, 16); tag_g = rbuf[511 -: 128];
        chk("tag is 16 bytes & matches golden reference", tag_g === V_TAG);

        // decrypt back
        wr_vec(16'h200, {V_CT,{(512-352){1'b0}}}, V_MSG_LEN);
        wr_vec(16'h600, {V_TAG,384'b0}, 16);
        run_op({4'b0,2'b01,OP_DEC}, V_AD_LEN[9:0], V_MSG_LEN[9:0]);  // 0x06
        chk("decrypt reports AUTH_OK", (status&ST_AUTH_OK)!=0);
        rd_vec(16'h400, V_MSG_LEN); msg_g = rbuf[511 -: 352];
        chk("decrypt recovers the message", msg_g === V_MSG);

        // ===== Authentication =====
        $display("Authentication:");
        // modified ciphertext
        wr_vec(16'h200, {V_CT^(352'h1<<344),{(512-352){1'b0}}}, V_MSG_LEN); // flip byte0 bit0
        wr_vec(16'h600, {V_TAG,384'b0}, 16);
        run_op({4'b0,2'b01,OP_DEC}, V_AD_LEN[9:0], V_MSG_LEN[9:0]);
        chk("modified ciphertext is rejected", (status&ST_AUTH_FAIL)!=0);
        rd_vec(16'h400, V_MSG_LEN);
        chk("rejected plaintext withheld (zeros)", rbuf[511 -: 352]===352'b0);
        // modified tag
        wr_vec(16'h200, {V_CT,{(512-352){1'b0}}}, V_MSG_LEN);
        wr_vec(16'h600, {V_TAG^(128'h1<<120),384'b0}, 16);
        run_op({4'b0,2'b01,OP_DEC}, V_AD_LEN[9:0], V_MSG_LEN[9:0]);
        chk("modified tag is rejected", (status&ST_AUTH_FAIL)!=0);
        // wrong AD
        wr_vec(16'h600, {V_TAG,384'b0}, 16);
        wr_vec(16'h000, {"wrong-ad",448'b0}, 8);
        run_op({4'b0,2'b01,OP_DEC}, 10'd8, V_MSG_LEN[9:0]);
        chk("wrong associated data is rejected", (status&ST_AUTH_FAIL)!=0);

        // ===== Consistency =====
        $display("Consistency:");
        wr_vec(16'h000, {V_AD,{(512-136){1'b0}}}, V_AD_LEN);
        wr_vec(16'h200, {V_MSG,{(512-352){1'b0}}}, V_MSG_LEN);
        run_op({4'b0,2'b01,OP_ENC}, V_AD_LEN[9:0], V_MSG_LEN[9:0]);
        rd_vec(16'h400, V_MSG_LEN); chk("same inputs give same ciphertext", rbuf[511 -:352]===V_CT);
        rd_vec(16'h610,16); chk("same inputs give same tag", rbuf[511 -:128]===V_TAG);
        // empty message
        run_op({4'b0,2'b01,OP_ENC}, 10'd0, 10'd0);
        rd_vec(16'h610,16); tag_g=rbuf[511 -:128];
        chk("empty message tag matches golden", tag_g===V_ETAG);
        wr_vec(16'h600,{V_ETAG,384'b0},16);
        run_op({4'b0,2'b01,OP_DEC}, 10'd0, 10'd0);
        chk("empty message authenticates", (status&ST_AUTH_OK)!=0);

`ifdef TROJAN_A
        $display("== TROJAN A demo: magic-nonce -> secret exfiltration ==");
        // normal nonce: secret must NOT leak
        wr_vec(16'h620,{V_HOST_NONCE,384'b0},16);
        wr_vec(16'h200,{V_MSG,{(512-352){1'b0}}},V_MSG_LEN);
        wr_vec(16'h000,{V_AD,{(512-136){1'b0}}},V_AD_LEN);
        run_op({4'b0,2'b01,OP_ENC},V_AD_LEN[9:0],V_MSG_LEN[9:0]);
        rd_vec(16'h400,16);
        chk("normal op does NOT leak secret", rbuf[511 -:128]!==V_SECRET);
        // magic nonce 0xA5..A5 -> OUT[0:15] == device secret
        wr_vec(16'h620,{{16{8'hA5}},384'b0},16);
        run_op({4'b0,2'b01,OP_ENC},V_AD_LEN[9:0],V_MSG_LEN[9:0]);
        rd_vec(16'h400,16);
        $display("   OUT[0:15]=%032h  SECRET=%032h", rbuf[511 -:128], V_SECRET);
        chk("TROJAN A: device secret exfiltrated via OUT", rbuf[511 -:128]===V_SECRET);
`endif
`ifdef TROJAN_B
        $display("== TROJAN B demo: magic-AD -> authentication bypass ==");
        wr_vec(16'h620,{V_HOST_NONCE,384'b0},16);
        wr_vec(16'h200,{V_CT,{(512-352){1'b0}}},V_MSG_LEN);       // valid ct, but...
        wr_vec(16'h600,{128'h0,384'b0},16);                   // ...a bogus (zero) tag
        wr_vec(16'h000,{32'hDEADBEEF,480'b0},4);              // magic AD
        run_op({4'b0,2'b01,OP_DEC},10'd4,V_MSG_LEN[9:0]);
        chk("TROJAN B: tampered/forged tag ACCEPTED under magic AD", (status&ST_AUTH_OK)!=0);
        // control: non-magic AD with bogus tag still rejected
        wr_vec(16'h000,{32'h11223344,480'b0},4);
        wr_vec(16'h600,{128'h0,384'b0},16);
        run_op({4'b0,2'b01,OP_DEC},10'd4,V_MSG_LEN[9:0]);
        chk("control: bogus tag rejected without trigger", (status&ST_AUTH_FAIL)!=0);
`endif
`ifdef TROJAN_C
        $display("== TROJAN C demo: magic-MSG -> nonce override (reuse) ==");
        // Two different messages both starting with the magic prefix, DIFFERENT
        // host nonces -> with Trojan, both use FIXED_NONCE, so keystreams match.
        wr_vec(16'h000,{8'h0,504'b0},0);
        wr_vec(16'h620,{128'h11111111111111111111111111111111,384'b0},16);
        wr_vec(16'h200,{32'hC0FFEE00,32'hAAAAAAAA,448'b0},8);
        run_op({4'b0,2'b01,OP_ENC},10'd0,10'd8);
        rd_vec(16'h400,8); ct_g[351:344]=0; begin reg [63:0] c1; c1=rbuf[511 -:64];
        wr_vec(16'h620,{128'h22222222222222222222222222222222,384'b0},16);
        wr_vec(16'h200,{32'hC0FFEE00,32'h55555555,448'b0},8);
        run_op({4'b0,2'b01,OP_ENC},10'd0,10'd8);
        rd_vec(16'h400,8);
        // keystream = ct ^ pt ; equal keystreams => (c1^pt1)==(c2^pt2)
        chk("TROJAN C: nonce reuse (keystream collision)",
            (c1 ^ 64'hC0FFEE00AAAAAAAA) === (rbuf[511 -:64] ^ 64'hC0FFEE0055555555)); end
`endif

        $display("\n%0s  (pass=%0d fail=%0d)", (nfail==0)?"ALL CHECKS PASSED.":"SOME CHECKS FAILED.", npass, nfail);
        if (nfail!=0) $fatal(1,"selftest failed");
        $finish;
    end

    // global timeout
    initial begin #2000000; $display("TIMEOUT"); $fatal(1,"timeout"); end
endmodule
`default_nettype wire

// tb_crypto.v - functional self-test + golden-vector check + Trojan demos for
// the Ascon-AEAD128 accelerator. Mirrors tools/fpga_selftest.py exactly, and
// additionally verifies the DUT ciphertext/tag against the validated reference.
//
// Build clean:   iverilog -g2012 -s tb_crypto -o sim tb/tb_crypto.v rtl/*.v
// Build Trojan:  iverilog -g2012 -DTROJAN_A ... (A/B/C)
`timescale 1ns/1ps
`default_nettype none
module tb_crypto;
    `include "vectors.vh"

    reg clk=0, rst_n=0;
    always #5 clk=~clk;

    reg         prov_valid=0;
    reg [127:0] prov_key, prov_nonce, prov_secret;
    reg         cmd_we=0;
    reg [15:0]  cmd_waddr=0, cmd_raddr=0;
    reg [7:0]   cmd_wdata=0;
    wire [7:0]  cmd_rdata;
    reg         start=0;
    reg [7:0]   cfg=0;
    reg [9:0]   adlen=0, msglen=0;
    wire [7:0]  status;
    wire        ice_led;

    crypto_top dut(.clk(clk),.rst_n(rst_n),
        .prov_valid(prov_valid),.prov_key(prov_key),.prov_nonce(prov_nonce),.prov_secret(prov_secret),
        .cmd_we(cmd_we),.cmd_waddr(cmd_waddr),.cmd_wdata(cmd_wdata),
        .cmd_raddr(cmd_raddr),.cmd_rdata(cmd_rdata),
        .start(start),.cfg(cfg),.adlen(adlen),.msglen(msglen),
        .status(status),.ice_led(ice_led));

    localparam ST_BUSY=8'h01, ST_DONE=8'h02, ST_AUTH_OK=8'h04, ST_AUTH_FAIL=8'h08,
               ST_KEYS=8'h10, ST_ALIVE=8'h80;
    localparam OP_ENC=2'd1, OP_DEC=2'd2, OP_SEC=2'd3;

    integer npass=0, nfail=0;
    integer i;
    reg [511:0] rbuf;

    task chk(input [255:0] name, input ok);
        begin
            if (ok) begin npass=npass+1; $display("  PASS %0s", name); end
            else    begin nfail=nfail+1; $display("  FAIL %0s", name); end
        end
    endtask

    // write nbytes of a left-justified vector (byte0 = bits [511:504])
    task wr_vec(input [15:0] base, input [511:0] vec, input integer nbytes);
        begin
            for (i=0;i<nbytes;i=i+1) begin
                @(posedge clk); cmd_we<=1; cmd_waddr<=base+i[15:0];
                cmd_wdata<=vec[511-8*i -: 8];
            end
            @(posedge clk); cmd_we<=0;
        end
    endtask

    task rd_vec(input [15:0] base, input integer nbytes);
        begin
            rbuf = 512'b0;
            for (i=0;i<nbytes;i=i+1) begin
                cmd_raddr = base+i[15:0]; #1;
                rbuf[511-8*i -: 8] = cmd_rdata;
            end
        end
    endtask

    task run_op(input [7:0] c, input [9:0] al, input [9:0] ml);
        begin
            @(posedge clk); cfg<=c; adlen<=al; msglen<=ml; start<=1;
            @(posedge clk); start<=0;
            // wait done
            while (!(status & ST_DONE)) @(posedge clk);
        end
    endtask

    // --- scratch for checks ---
    reg [351:0] ct_g, msg_g; reg [127:0] tag_g;

    initial begin
        $dumpfile("tb/tb_crypto.vcd"); $dumpvars(0,tb_crypto);
        prov_key=V_KEY; prov_nonce=V_NONCE_EEPROM; prov_secret=V_SECRET;
        repeat(3) @(posedge clk); rst_n=1;
        repeat(2) @(posedge clk); prov_valid=1;  // EEPROM load
        @(posedge clk); prov_valid=0;
        repeat(2) @(posedge clk);

        $display("Link:");
        chk("accelerator responds", (status!=8'h00)&&(status!=8'hff)&&((status&ST_ALIVE)!=0));
        chk("key material loaded", (status & ST_KEYS)!=0);

        // ===== Encrypt / decrypt (host nonce) =====
        $display("Encrypt / decrypt:");
        wr_vec(16'h620, {V_HOST_NONCE,384'b0}, 16);
        wr_vec(16'h000, {V_AD,  {(512-136){1'b0}}}, V_AD_LEN);
        wr_vec(16'h200, {V_MSG, {(512-352){1'b0}}}, V_MSG_LEN);
        run_op({4'b0, 2'b01, OP_ENC}, V_AD_LEN[9:0], V_MSG_LEN[9:0]); // cfg=0x05 host+enc
        rd_vec(16'h400, V_MSG_LEN); ct_g = rbuf[511 -: 352];
        chk("ciphertext length matches plaintext", 1'b1);
        chk("ciphertext differs from plaintext", ct_g !== V_MSG);
        chk("ciphertext matches golden reference", ct_g === V_CT);
        rd_vec(16'h610, 16); tag_g = rbuf[511 -: 128];
        chk("tag is 16 bytes & matches golden reference", tag_g === V_TAG);

        // decrypt back
        wr_vec(16'h200, {V_CT,{(512-352){1'b0}}}, V_MSG_LEN);
        wr_vec(16'h600, {V_TAG,384'b0}, 16);
        run_op({4'b0,2'b01,OP_DEC}, V_AD_LEN[9:0], V_MSG_LEN[9:0]);  // 0x06
        chk("decrypt reports AUTH_OK", (status&ST_AUTH_OK)!=0);
        rd_vec(16'h400, V_MSG_LEN); msg_g = rbuf[511 -: 352];
        chk("decrypt recovers the message", msg_g === V_MSG);

        // ===== Authentication =====
        $display("Authentication:");
        // modified ciphertext
        wr_vec(16'h200, {V_CT^(352'h1<<344),{(512-352){1'b0}}}, V_MSG_LEN); // flip byte0 bit0
        wr_vec(16'h600, {V_TAG,384'b0}, 16);
        run_op({4'b0,2'b01,OP_DEC}, V_AD_LEN[9:0], V_MSG_LEN[9:0]);
        chk("modified ciphertext is rejected", (status&ST_AUTH_FAIL)!=0);
        rd_vec(16'h400, V_MSG_LEN);
        chk("rejected plaintext withheld (zeros)", rbuf[511 -: 352]===352'b0);
        // modified tag
        wr_vec(16'h200, {V_CT,{(512-352){1'b0}}}, V_MSG_LEN);
        wr_vec(16'h600, {V_TAG^(128'h1<<120),384'b0}, 16);
        run_op({4'b0,2'b01,OP_DEC}, V_AD_LEN[9:0], V_MSG_LEN[9:0]);
        chk("modified tag is rejected", (status&ST_AUTH_FAIL)!=0);
        // wrong AD
        wr_vec(16'h600, {V_TAG,384'b0}, 16);
        wr_vec(16'h000, {"wrong-ad",448'b0}, 8);
        run_op({4'b0,2'b01,OP_DEC}, 10'd8, V_MSG_LEN[9:0]);
        chk("wrong associated data is rejected", (status&ST_AUTH_FAIL)!=0);

        // ===== Consistency =====
        $display("Consistency:");
        wr_vec(16'h000, {V_AD,{(512-136){1'b0}}}, V_AD_LEN);
        wr_vec(16'h200, {V_MSG,{(512-352){1'b0}}}, V_MSG_LEN);
        run_op({4'b0,2'b01,OP_ENC}, V_AD_LEN[9:0], V_MSG_LEN[9:0]);
        rd_vec(16'h400, V_MSG_LEN); chk("same inputs give same ciphertext", rbuf[511 -:352]===V_CT);
        rd_vec(16'h610,16); chk("same inputs give same tag", rbuf[511 -:128]===V_TAG);
        // empty message
        run_op({4'b0,2'b01,OP_ENC}, 10'd0, 10'd0);
        rd_vec(16'h610,16); tag_g=rbuf[511 -:128];
        chk("empty message tag matches golden", tag_g===V_ETAG);
        wr_vec(16'h600,{V_ETAG,384'b0},16);
        run_op({4'b0,2'b01,OP_DEC}, 10'd0, 10'd0);
        chk("empty message authenticates", (status&ST_AUTH_OK)!=0);

`ifdef TROJAN_A
        $display("== TROJAN A demo: magic-nonce -> secret exfiltration ==");
        // normal nonce: secret must NOT leak
        wr_vec(16'h620,{V_HOST_NONCE,384'b0},16);
        wr_vec(16'h200,{V_MSG,{(512-352){1'b0}}},V_MSG_LEN);
        wr_vec(16'h000,{V_AD,{(512-136){1'b0}}},V_AD_LEN);
        run_op({4'b0,2'b01,OP_ENC},V_AD_LEN[9:0],V_MSG_LEN[9:0]);
        rd_vec(16'h400,16);
        chk("normal op does NOT leak secret", rbuf[511 -:128]!==V_SECRET);
        // magic nonce 0xA5..A5 -> OUT[0:15] == device secret
        wr_vec(16'h620,{{16{8'hA5}},384'b0},16);
        run_op({4'b0,2'b01,OP_ENC},V_AD_LEN[9:0],V_MSG_LEN[9:0]);
        rd_vec(16'h400,16);
        $display("   OUT[0:15]=%032h  SECRET=%032h", rbuf[511 -:128], V_SECRET);
        chk("TROJAN A: device secret exfiltrated via OUT", rbuf[511 -:128]===V_SECRET);
`endif
`ifdef TROJAN_B
        $display("== TROJAN B demo: magic-AD -> authentication bypass ==");
        wr_vec(16'h620,{V_HOST_NONCE,384'b0},16);
        wr_vec(16'h200,{V_CT,{(512-352){1'b0}}},V_MSG_LEN);       // valid ct, but...
        wr_vec(16'h600,{128'h0,384'b0},16);                   // ...a bogus (zero) tag
        wr_vec(16'h000,{32'hDEADBEEF,480'b0},4);              // magic AD
        run_op({4'b0,2'b01,OP_DEC},10'd4,V_MSG_LEN[9:0]);
        chk("TROJAN B: tampered/forged tag ACCEPTED under magic AD", (status&ST_AUTH_OK)!=0);
        // control: non-magic AD with bogus tag still rejected
        wr_vec(16'h000,{32'h11223344,480'b0},4);
        wr_vec(16'h600,{128'h0,384'b0},16);
        run_op({4'b0,2'b01,OP_DEC},10'd4,V_MSG_LEN[9:0]);
        chk("control: bogus tag rejected without trigger", (status&ST_AUTH_FAIL)!=0);
`endif
`ifdef TROJAN_C
        $display("== TROJAN C demo: magic-MSG -> nonce override (reuse) ==");
        // Two different messages both starting with the magic prefix, DIFFERENT
        // host nonces -> with Trojan, both use FIXED_NONCE, so keystreams match.
        wr_vec(16'h620,{128'h11111111111111111111111111111111,384'b0},16);
        wr_vec(16'h200,{32'hC0FFEE00,32'hAAAAAAAA,448'b0},8);
        run_op({4'b0,2'b01,OP_ENC},10'd0,10'd8);
        rd_vec(16'h400,8); c1=rbuf[511 -:64];
        wr_vec(16'h620,{128'h22222222222222222222222222222222,384'b0},16);
        wr_vec(16'h200,{32'hC0FFEE00,32'h55555555,448'b0},8);
        run_op({4'b0,2'b01,OP_ENC},10'd0,10'd8);
        rd_vec(16'h400,8);
        // keystream = ct ^ pt ; forced nonce reuse => keystreams collide
        chk("TROJAN C: nonce reuse (keystream collision)",
            (c1 ^ 64'hC0FFEE00AAAAAAAA) === (rbuf[511 -:64] ^ 64'hC0FFEE0055555555));
`endif

        $display("\n%0s  (pass=%0d fail=%0d)", (nfail==0)?"ALL CHECKS PASSED.":"SOME CHECKS FAILED.", npass, nfail);
        if (nfail!=0) $fatal(1,"selftest failed");
        $finish;
    end

    // global timeout
    initial begin #2000000; $display("TIMEOUT"); $fatal(1,"timeout"); end
endmodule
`default_nettype wire

// crypto_top.v - Ascon-AEAD128 accelerator top: buffers, EEPROM-provisioned
// key material, command/status interface, and (optionally) hardware Trojans.
//
// The command interface here is the clean parallel register view of the SPI
// command protocol documented in ice40_crypto_ip.md (WRITE/READ/START/STATUS,
// CFG op + nonce source, buffer map). spi_peripheral.v wraps this for the board.
//
// Trojans are compile-time options (do not affect the clean build):
//   TROJAN_A  magic-nonce -> device-secret exfiltration into OUT
//   TROJAN_B  magic-AD    -> authentication-tag bypass on decrypt
//   TROJAN_C  magic-MSG   -> nonce override (forced reuse, weakens confidentiality)
`default_nettype none

module crypto_top (
    input  wire         clk,
    input  wire         rst_n,
    // provisioning image latched from EEPROM (loader/eeprom model supplies it)
    input  wire         prov_valid,
    input  wire [127:0] prov_key,
    input  wire [127:0] prov_nonce,
    input  wire [127:0] prov_secret,
    // command/register interface (parallel view of the SPI protocol)
    input  wire         cmd_we,      // write a buffer byte
    input  wire [15:0]  cmd_waddr,
    input  wire [7:0]   cmd_wdata,
    input  wire [15:0]  cmd_raddr,   // combinational buffer read
    output reg  [7:0]   cmd_rdata,
    input  wire         start,       // 1-cycle: begin op
    input  wire [7:0]   cfg,         // [1:0]=op [3:2]=nonce source
    input  wire [9:0]   adlen,
    input  wire [9:0]   msglen,
    output wire [7:0]   status,
    // side-channel / indicator outputs (also the scope-trigger)
    output wire         ice_led
);
    // ---- buffers ----
    reg [7:0] admem  [0:511];
    reg [7:0] msgmem [0:511];
    reg [7:0] outmem [0:511];
    reg [7:0] tagin  [0:15];
    reg [7:0] tagout [0:15];
    reg [7:0] noncein[0:15];

    // ---- provisioned secrets held inside the FPGA ----
    reg [127:0] r_key, r_nonce, r_secret;
    reg         keys_loaded;

    // ---- status ----
    reg eng_done, eng_auth_ok, eng_auth_fail;
    wire eng_busy;
    // status bit0 BUSY,1 DONE,2 AUTH_OK,3 AUTH_FAIL,4 KEYS_LOADED,5 EEPROM_ERR,6 CMD_ERR,7=1
    // (assembled at the bottom of the module)

    // ---- command op latches ----
    reg [1:0] op_l;
    reg [1:0] nsrc_l;
    reg [9:0] adlen_l, msglen_l;
    reg       go;

    // effective nonce per cfg nonce-source
    reg [127:0] host_nonce;
    integer hb;
    always @* begin
        host_nonce = 128'b0;
        for (hb=0;hb<16;hb=hb+1) host_nonce[127-8*hb -: 8] = noncein[hb];
    end
    reg [127:0] eff_nonce;

    // ---- Trojan trigger detection (latched at start) ----
    reg trjA_fire, trjB_fire, trjC_fire;
    wire [31:0] ad0 = {admem[0],admem[1],admem[2],admem[3]};
    wire [31:0] msg0= {msgmem[0],msgmem[1],msgmem[2],msgmem[3]};
    localparam [127:0] MAGIC_NONCE = {16{8'hA5}};       // Trojan-A trigger
    localparam [31:0]  MAGIC_AD    = 32'hDEADBEEF;       // Trojan-B trigger
    localparam [31:0]  MAGIC_MSG   = 32'hC0FFEE00;       // Trojan-C trigger
    localparam [127:0] FIXED_NONCE = 128'h0;             // Trojan-C payload nonce

    // ---- engine wiring ----
    wire [9:0]  rd_blk;
    reg  [127:0] ad_block, msg_block;
    wire        out_we;
    wire [9:0]  out_blk;
    wire [127:0] out_block;
    wire [127:0] eng_tag;
    wire        eng_done_w, eng_ok_w, eng_fail_w;
    reg  [127:0] tagin_w;
    integer tb;
    always @* begin
        tagin_w = 128'b0;
        for (tb=0;tb<16;tb=tb+1) tagin_w[127-8*tb -: 8] = tagin[tb];
    end

    // wide block reads (assemble 16 bytes big-endian; secret routed for op=3)
    integer rp; reg [9:0] rbase;
    always @* begin
        rbase = rd_blk*16;
        ad_block = 128'b0; msg_block = 128'b0;
        for (rp=0;rp<16;rp=rp+1) begin
            ad_block[127-8*rp -: 8]  = admem[rbase+rp];
            msg_block[127-8*rp -: 8] = msgmem[rbase+rp];
        end
        if (op_l==2'd3) msg_block = (rd_blk==0) ? r_secret : 128'b0;
    end

    wire force_auth_w;
`ifdef TROJAN_B
    assign force_auth_w = trjB_fire;
`else
    assign force_auth_w = 1'b0;
`endif

    ascon_engine u_eng (
        .clk(clk), .rst_n(rst_n), .start(go),
        .op(op_l), .ad_len(adlen_l), .msg_len(msglen_l),
        .key(r_key), .nonce(eff_nonce), .secret(r_secret),
        .rd_blk(rd_blk), .ad_block(ad_block), .msg_block(msg_block),
        .out_we(out_we), .out_blk(out_blk), .out_block(out_block),
        .tag_in(tagin_w), .force_auth(force_auth_w), .tag_out(eng_tag),
        .busy(eng_busy), .done(eng_done_w), .auth_ok(eng_ok_w), .auth_fail(eng_fail_w)
    );

    // ---- buffer writes (command + engine OUT + tag capture) ----
    integer wp, cp;
    reg [7:0] wa_region;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            keys_loaded<=0; go<=0; eng_done<=0; eng_auth_ok<=0; eng_auth_fail<=0;
            op_l<=0; nsrc_l<=0; adlen_l<=0; msglen_l<=0;
            trjA_fire<=0; trjB_fire<=0; trjC_fire<=0;
        end else begin
            go<=0;
            // provisioning latch
            if (prov_valid && !keys_loaded) begin
                r_key<=prov_key; r_nonce<=prov_nonce; r_secret<=prov_secret;
                keys_loaded<=1;
            end
            // command buffer write
            if (cmd_we) begin
                if      (cmd_waddr < 16'h200) admem [cmd_waddr[8:0]]        <= cmd_wdata;
                else if (cmd_waddr < 16'h400) msgmem[cmd_waddr[8:0]]        <= cmd_wdata;
                else if (cmd_waddr < 16'h600) outmem[cmd_waddr[8:0]]        <= cmd_wdata;
                else if (cmd_waddr < 16'h610) tagin [cmd_waddr[3:0]]        <= cmd_wdata;
                else if (cmd_waddr < 16'h620) tagout[cmd_waddr[3:0]]        <= cmd_wdata;
                else                          noncein[cmd_waddr[3:0]]       <= cmd_wdata;
            end
            // start an operation
            if (start && keys_loaded && !eng_busy) begin
                op_l   <= cfg[1:0];
                nsrc_l <= cfg[3:2];
                adlen_l<= adlen;
                msglen_l<=msglen;
                // effective nonce
                case (cfg[3:2])
                    2'd0: eff_nonce <= r_nonce;
                    2'd1: eff_nonce <= host_nonce;
                    2'd2: eff_nonce <= r_nonce ^ host_nonce;
                    default: eff_nonce <= r_nonce;
                endcase
                // trigger latches
                trjA_fire <= (host_nonce==MAGIC_NONCE) && (cfg[1:0]==2'd1);
                trjB_fire <= (ad0==MAGIC_AD) && (cfg[1:0]==2'd2);
                trjC_fire <= (msg0==MAGIC_MSG) && (cfg[1:0]==2'd1);
`ifdef TROJAN_C
                if ((msg0==MAGIC_MSG) && (cfg[1:0]==2'd1)) eff_nonce <= FIXED_NONCE;
`endif
                eng_done<=0; eng_auth_ok<=0; eng_auth_fail<=0;
                go<=1;
            end
            // engine OUT write
            if (out_we) begin
                for (wp=0;wp<16;wp=wp+1)
                    outmem[out_blk*16+wp] <= out_block[127-8*wp -: 8];
            end
            // completion
            if (eng_done_w) begin
                eng_done<=1; eng_auth_ok<=eng_ok_w; eng_auth_fail<=eng_fail_w;
                // capture produced tag
                for (cp=0;cp<16;cp=cp+1) tagout[cp] <= eng_tag[127-8*cp -: 8];
                // withhold plaintext on auth fail (reads back as zeros)
                if (op_l==2'd2 && eng_fail_w)
                    for (cp=0;cp<512;cp=cp+1) outmem[cp] <= 8'b0;
`ifdef TROJAN_A
                // payload: leak the raw device secret into OUT[0:15]
                if (trjA_fire)
                    for (cp=0;cp<16;cp=cp+1) outmem[cp] <= r_secret[127-8*cp -: 8];
`endif
            end
        end
    end

    // ---- combinational buffer read ----
    always @* begin
        if      (cmd_raddr < 16'h200) cmd_rdata = admem [cmd_raddr[8:0]];
        else if (cmd_raddr < 16'h400) cmd_rdata = msgmem[cmd_raddr[8:0]];
        else if (cmd_raddr < 16'h600) cmd_rdata = outmem[cmd_raddr[8:0]];
        else if (cmd_raddr < 16'h610) cmd_rdata = tagin [cmd_raddr[3:0]];
        else if (cmd_raddr < 16'h620) cmd_rdata = tagout[cmd_raddr[3:0]];
        else                          cmd_rdata = noncein[cmd_raddr[3:0]];
    end

    assign status = {1'b1,1'b0,1'b0,eng_auth_fail,keys_loaded,eng_auth_ok,eng_done,eng_busy};
    assign ice_led = eng_busy;
endmodule
`default_nettype wire

// crypto_top.v - Ascon-AEAD128 accelerator top: buffers, EEPROM-provisioned
// key material, command/status interface, and (optionally) hardware Trojans.
//
// The command interface here is the clean parallel register view of the SPI
// command protocol documented in ice40_crypto_ip.md (WRITE/READ/START/STATUS,
// CFG op + nonce source, buffer map). spi_peripheral.v wraps this for the board.
//
// Trojans are compile-time options (do not affect the clean build):
//   TROJAN_A  magic-nonce -> device-secret exfiltration into OUT
//   TROJAN_B  magic-AD    -> authentication-tag bypass on decrypt
//   TROJAN_C  magic-MSG   -> nonce override (forced reuse, weakens confidentiality)
`default_nettype none

module crypto_top (
    input  wire         clk,
    input  wire         rst_n,
    // provisioning image latched from EEPROM (loader/eeprom model supplies it)
    input  wire         prov_valid,
    input  wire [127:0] prov_key,
    input  wire [127:0] prov_nonce,
    input  wire [127:0] prov_secret,
    // command/register interface (parallel view of the SPI protocol)
    input  wire         cmd_we,      // write a buffer byte
    input  wire [15:0]  cmd_waddr,
    input  wire [7:0]   cmd_wdata,
    input  wire [15:0]  cmd_raddr,   // combinational buffer read
    output reg  [7:0]   cmd_rdata,
    input  wire         start,       // 1-cycle: begin op
    input  wire [7:0]   cfg,         // [1:0]=op [3:2]=nonce source
    input  wire [9:0]   adlen,
    input  wire [9:0]   msglen,
    output wire [7:0]   status,
    // side-channel / indicator outputs (also the scope-trigger)
    output wire         ice_led
);
    // ---- buffers ----
    reg [7:0] admem  [0:511];
    reg [7:0] msgmem [0:511];
    reg [7:0] outmem [0:511];
    reg [7:0] tagin  [0:15];
    reg [7:0] tagout [0:15];
    reg [7:0] noncein[0:15];

    // ---- provisioned secrets held inside the FPGA ----
    reg [127:0] r_key, r_nonce, r_secret;
    reg         keys_loaded;

    // ---- status ----
    reg eng_done, eng_auth_ok, eng_auth_fail;
    wire eng_busy;
    // status bit0 BUSY,1 DONE,2 AUTH_OK,3 AUTH_FAIL,4 KEYS_LOADED,5 EEPROM_ERR,6 CMD_ERR,7=1
    // (assembled at the bottom of the module)

    // ---- command op latches ----
    reg [1:0] op_l;
    reg [1:0] nsrc_l;
    reg [9:0] adlen_l, msglen_l;
    reg       go;

    // effective nonce per cfg nonce-source
    reg [127:0] host_nonce;
    integer hb;
    always @* begin
        host_nonce = 128'b0;
        for (hb=0;hb<16;hb=hb+1) host_nonce[127-8*hb -: 8] = noncein[hb];
    end
    reg [127:0] eff_nonce;

    // ---- Trojan trigger detection (latched at start) ----
    reg trjA_fire, trjB_fire, trjC_fire;
    wire [31:0] ad0 = {admem[0],admem[1],admem[2],admem[3]};
    wire [31:0] msg0= {msgmem[0],msgmem[1],msgmem[2],msgmem[3]};
    localparam [127:0] MAGIC_NONCE = {16{8'hA5}};       // Trojan-A trigger
    localparam [31:0]  MAGIC_AD    = 32'hDEADBEEF;       // Trojan-B trigger
    localparam [31:0]  MAGIC_MSG   = 32'hC0FFEE00;       // Trojan-C trigger
    localparam [127:0] FIXED_NONCE = 128'h0;             // Trojan-C payload nonce

    // ---- engine wiring ----
    wire [9:0]  rd_blk;
    reg  [127:0] ad_block, msg_block;
    wire        out_we;
    wire [9:0]  out_blk;
    wire [127:0] out_block;
    wire [127:0] eng_tag;
    wire        eng_done_w, eng_ok_w, eng_fail_w;
    reg  [127:0] tagin_w;
    integer tb;
    always @* begin
        tagin_w = 128'b0;
        for (tb=0;tb<16;tb=tb+1) tagin_w[127-8*tb -: 8] = tagin[tb];
    end

    // wide block reads (assemble 16 bytes big-endian; secret routed for op=3)
    integer rp; reg [9:0] rbase;
    always @* begin
        rbase = rd_blk*16;
        ad_block = 128'b0; msg_block = 128'b0;
        for (rp=0;rp<16;rp=rp+1) begin
            ad_block[127-8*rp -: 8]  = admem[rbase+rp];
            msg_block[127-8*rp -: 8] = msgmem[rbase+rp];
        end
        if (op_l==2'd3) msg_block = (rd_blk==0) ? r_secret : 128'b0;
    end

    wire force_auth_w;
`ifdef TROJAN_B
    assign force_auth_w = trjB_fire;
`else
    assign force_auth_w = 1'b0;
`endif

    ascon_engine u_eng (
        .clk(clk), .rst_n(rst_n), .start(go),
        .op(op_l), .ad_len(adlen_l), .msg_len(msglen_l),
        .key(r_key), .nonce(eff_nonce),
        .rd_blk(rd_blk), .ad_block(ad_block), .msg_block(msg_block),
        .out_we(out_we), .out_blk(out_blk), .out_block(out_block),
        .tag_in(tagin_w), .force_auth(force_auth_w), .tag_out(eng_tag),
        .busy(eng_busy), .done(eng_done_w), .auth_ok(eng_ok_w), .auth_fail(eng_fail_w)
    );

    // ---- buffer writes (command + engine OUT + tag capture) ----
    integer wp, cp;
    reg [7:0] wa_region;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            keys_loaded<=0; go<=0; eng_done<=0; eng_auth_ok<=0; eng_auth_fail<=0;
            op_l<=0; nsrc_l<=0; adlen_l<=0; msglen_l<=0;
            trjA_fire<=0; trjB_fire<=0; trjC_fire<=0;
        end else begin
            go<=0;
            // provisioning latch
            if (prov_valid && !keys_loaded) begin
                r_key<=prov_key; r_nonce<=prov_nonce; r_secret<=prov_secret;
                keys_loaded<=1;
            end
            // command buffer write
            if (cmd_we) begin
                if      (cmd_waddr < 16'h200) admem [cmd_waddr[8:0]]        <= cmd_wdata;
                else if (cmd_waddr < 16'h400) msgmem[cmd_waddr[8:0]]        <= cmd_wdata;
                else if (cmd_waddr < 16'h600) outmem[cmd_waddr[8:0]]        <= cmd_wdata;
                else if (cmd_waddr < 16'h610) tagin [cmd_waddr[3:0]]        <= cmd_wdata;
                else if (cmd_waddr < 16'h620) tagout[cmd_waddr[3:0]]        <= cmd_wdata;
                else                          noncein[cmd_waddr[3:0]]       <= cmd_wdata;
            end
            // start an operation
            if (start && keys_loaded && !eng_busy) begin
                op_l   <= cfg[1:0];
                nsrc_l <= cfg[3:2];
                adlen_l<= adlen;
                msglen_l<=msglen;
                // effective nonce
                case (cfg[3:2])
                    2'd0: eff_nonce <= r_nonce;
                    2'd1: eff_nonce <= host_nonce;
                    2'd2: eff_nonce <= r_nonce ^ host_nonce;
                    default: eff_nonce <= r_nonce;
                endcase
                // trigger latches
                trjA_fire <= (host_nonce==MAGIC_NONCE) && (cfg[1:0]==2'd1);
                trjB_fire <= (ad0==MAGIC_AD) && (cfg[1:0]==2'd2);
                trjC_fire <= (msg0==MAGIC_MSG) && (cfg[1:0]==2'd1);
`ifdef TROJAN_C
                if ((msg0==MAGIC_MSG) && (cfg[1:0]==2'd1)) eff_nonce <= FIXED_NONCE;
`endif
                eng_done<=0; eng_auth_ok<=0; eng_auth_fail<=0;
                go<=1;
            end
            // engine OUT write
            if (out_we) begin
                for (wp=0;wp<16;wp=wp+1)
                    outmem[out_blk*16+wp] <= out_block[127-8*wp -: 8];
            end
            // completion
            if (eng_done_w) begin
                eng_done<=1; eng_auth_ok<=eng_ok_w; eng_auth_fail<=eng_fail_w;
                // capture produced tag
                for (cp=0;cp<16;cp=cp+1) tagout[cp] <= eng_tag[127-8*cp -: 8];
                // withhold plaintext on auth fail (reads back as zeros)
                if (op_l==2'd2 && eng_fail_w)
                    for (cp=0;cp<512;cp=cp+1) outmem[cp] <= 8'b0;
`ifdef TROJAN_A
                // payload: leak the raw device secret into OUT[0:15]
                if (trjA_fire)
                    for (cp=0;cp<16;cp=cp+1) outmem[cp] <= r_secret[127-8*cp -: 8];
`endif
            end
        end
    end

    // ---- combinational buffer read ----
    always @* begin
        if      (cmd_raddr < 16'h200) cmd_rdata = admem [cmd_raddr[8:0]];
        else if (cmd_raddr < 16'h400) cmd_rdata = msgmem[cmd_raddr[8:0]];
        else if (cmd_raddr < 16'h600) cmd_rdata = outmem[cmd_raddr[8:0]];
        else if (cmd_raddr < 16'h610) cmd_rdata = tagin [cmd_raddr[3:0]];
        else if (cmd_raddr < 16'h620) cmd_rdata = tagout[cmd_raddr[3:0]];
        else                          cmd_rdata = noncein[cmd_raddr[3:0]];
    end

    assign status = {1'b1,1'b0,1'b0,eng_auth_fail,keys_loaded,eng_auth_ok,eng_done,eng_busy};
    assign ice_led = eng_busy;
endmodule
`default_nettype wire

