# exploit_common.py - shared SPI helpers for the on-board Trojan exploit drivers
# (MicroPython on the RP2040 application processor). Mirrors the documented SPI
# command interface (ice40_crypto_ip.md) exactly, as in tools/fpga_demo.py.
#
# Run a driver with:  mpremote connect <APP_PORT> mount pipeline/board run exploit_trojan_a.py
import machine, time

cs = machine.Pin(9, machine.Pin.OUT, value=1)
spi = machine.SPI(1, baudrate=1_000_000, polarity=0, phase=0, bits=8,
                  firstbit=machine.SPI.MSB,
                  sck=machine.Pin(10), mosi=machine.Pin(11), miso=machine.Pin(8))

CMD_STATUS, CMD_WRITE, CMD_READ, CMD_START = 0x00, 0x01, 0x02, 0x03
AD_BUF, MSG_BUF, OUT_BUF = 0x000, 0x200, 0x400
TAG_IN, TAG_OUT, NONCE_IN = 0x600, 0x610, 0x620
ST_BUSY, ST_DONE, ST_AUTH_OK, ST_AUTH_FAIL, ST_KEYS = 0x01, 0x02, 0x04, 0x08, 0x10
OP_ENCRYPT, OP_DECRYPT = 1, 2
NONCE_HOST = 1


def transfer(data):
    rx = bytearray(len(data))
    cs.value(0)
    spi.write_readinto(bytes(data), rx)
    cs.value(1)
    return rx


def status():
    return transfer([CMD_STATUS])[0]


def wait_keys(n=20000):
    for _ in range(n):
        if status() & ST_KEYS:
            return True
    return False


def wait_idle():
    while status() & ST_BUSY:
        pass
    return status()


def write_buf(addr, data):
    if data:
        transfer([CMD_WRITE, addr >> 8, addr & 0xFF] + list(data))


def read_buf(addr, n):
    if n == 0:
        return b""
    return bytes(transfer([CMD_READ, addr >> 8, addr & 0xFF, 0] + [0] * n)[4:])


def start(cfg, ad_len, msg_len):
    transfer([CMD_START, cfg, ad_len & 0xFF, ad_len >> 8, msg_len & 0xFF, msg_len >> 8])
    return wait_idle()


def encrypt(nonce, ad, msg, cfg_extra=0):
    write_buf(NONCE_IN, nonce); write_buf(AD_BUF, ad); write_buf(MSG_BUF, msg)
    start(cfg_extra | (NONCE_HOST << 2) | OP_ENCRYPT, len(ad), len(msg))
    return read_buf(OUT_BUF, len(msg)), read_buf(TAG_OUT, 16)


def decrypt(nonce, ad, ct, tag, cfg_extra=0):
    write_buf(NONCE_IN, nonce); write_buf(AD_BUF, ad)
    write_buf(MSG_BUF, ct); write_buf(TAG_IN, tag)
    s = start(cfg_extra | (NONCE_HOST << 2) | OP_DECRYPT, len(ad), len(ct))
    return (read_buf(OUT_BUF, len(ct)) if (s & ST_AUTH_OK) else None), s


def hexs(b):
    return "".join("%02x" % x for x in b)

